To Reproduce
Steps to reproduce the behavior:

sample code:

#include "torch/script.h"
#include <exception>
#include <sys/time.h>
#include <string>
#include <vector>

class MyTimer {
public:
    static long GetTimeStamp() {
        struct timeval now;
        gettimeofday(&now, NULL);
        return 1000000 * now.tv_sec + now.tv_usec;
    }
    static double GetElapsedTime(long& start, long& end) {
        return (end - start) / 1000000.0;
    }
};

class ForwardModel {
public:
    void Init(std::string model_file) {
        try {
            std::cout << " loading model " << std::endl;
            module_ = torch::jit::load(model_file);
        } catch (const c10::Error& e) {
            std::cout << " error loading the model! " << std::endl;
            return;
        }
    }

    at::Tensor ModelForward(std::vector<float>& signal, size_t start, size_t end) {
        std::vector<torch::jit::IValue> inputs = {torch::unsqueeze(torch::unsqueeze(torch::tensor(at::ArrayRef<float>(&signal[start], &signal[end])), 0), 0).cuda()};
        torch::NoGradGuard no_grad;
        return std::move(module_.forward(inputs).toTensor().exp().cpu().squeeze(0));
    }

protected:
    torch::jit::script::Module module_;
};

int main(int argc, char** argv) {
    std::string model_path = "/Path/To/Model/Kirky@v2.pt";
    ForwardModel model;
    model.Init(model_path);
    std::vector<float> input(200000, 3);
    for (int i = 0; i < 40; i++) {
        int size = 14700 + i * 100;  // 14700 can be any other numbers

        long start = MyTimer::GetTimeStamp();
        auto output = model.ModelForward(input, 0, size);
        long end = MyTimer::GetTimeStamp();

        std::cout << "loop " << i << " <cost> " << MyTimer::GetElapsedTime(start, end) << " s. size: " << size << std::endl;
    }
    return 0;
}



